framework_component_specs.ArticleEnhancer:
# ArticleEnhancer

## Purpose
Client-side article wrapper that generates a TOC and HowTo/MediaObject JSON-LD. Save as `.html`; use native DOM APIs, not framework imports.

## Configuration
Set attributes on `[data-article-enhancer]`.

| Original prop | HTML equivalent | Type | Default | Description |
|---|---|---|---|---|
| `articleTitle` | `data-article-title` | string | Required | Structured-data title |
| `contentSelector` | `data-content-selector` | string | Required | Content CSS selector |
| `articleDescription` | `data-article-description` | string | — | Structured-data description |
| `enableToc` | `data-enable-toc` | boolean string | `"true"` | Generate TOC |
| `enableHowTo` | `data-enable-how-to` | boolean string | `"true"` | Inject HowTo |
| `enableMediaObject` | `data-enable-media-object` | boolean string | `"true"` | Describe images |
| `children` | Nested HTML | HTML | — | Wrapped article content |

## Semantic Hints
`enhancer`, `wrapper`, `article-wrapper`, `enhancement`, `seo`, `structured-data`, `meta`

## Usage and Behavior
Use in an article layout. Scan h2/h3 after parsing; preserve IDs, assign missing IDs, strip emoji from TOC labels, and nest h3 links beneath h2 links. Render into the wrapper's TOC placeholder. Explicitly mark procedural lists with `data-how-to`. Inject schemas into `<head>`. Debounce content mutations; disconnect during generated writes to avoid observer loops. Without JavaScript, article content remains readable.

## Working Example
```html
<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><title>Getting Started with AI</title></head>
<body>
<main data-article-enhancer
  data-article-title="Getting Started with AI"
  data-article-description="A beginner's guide"
  data-content-selector="#article-content">
  <nav data-toc aria-label="Table of contents"></nav>
  <article id="article-content">
    <h2>Introduction</h2><p>Start here.</p>
    <h2>Step-by-Step Guide</h2>
    <h3>Preparation</h3>
    <ol data-how-to><li>Choose a tool.</li><li>Try a prompt.</li></ol>
  </article>
</main>
<script>
document.querySelectorAll('[data-article-enhancer]').forEach(w => {
  const d = w.dataset, c = w.querySelector(d.contentSelector);
  if (!c) return;
  const enabled = k => d[k] !== 'false';
  const schema = document.createElement('script');
  schema.type = 'application/ld+json';
  document.head.append(schema);
  let timer;
  const observer = new MutationObserver(() => {
    clearTimeout(timer);
    timer = setTimeout(scan, 150);
  });
  function scan() {
    observer.disconnect();
    const toc = w.querySelector('[data-toc]'), root = document.createElement('ol');
    let nested;
    c.querySelectorAll('h2,h3').forEach((h, i) => {
      if (!h.id) {
        let id = 'heading-' + i;
        while (document.getElementById(id)) id += '-';
        h.id = id;
      }
      const li = document.createElement('li'), a = document.createElement('a');
      a.href = '#' + encodeURIComponent(h.id);
      a.textContent = h.textContent.replace(/\p{Extended_Pictographic}|\uFE0F|\u200D/gu, '').trim();
      li.append(a);
      if (h.tagName === 'H2') {
        root.append(li);
        nested = document.createElement('ol');
        li.append(nested);
      } else (nested || root).append(li);
    });
    if (toc) toc.replaceChildren(...(enabled('enableToc') ? [root] : []));
    const graph = [];
    if (enabled('enableHowTo')) c.querySelectorAll('ol[data-how-to]').forEach(list => {
      graph.push({
        '@type': 'HowTo', name: d.articleTitle,
        description: d.articleDescription,
        step: [...list.children].map(li => ({
          '@type': 'HowToStep', text: li.textContent.trim()
        }))
      });
    });
    if (enabled('enableMediaObject')) c.querySelectorAll('img[src]').forEach(img => {
      graph.push({'@type': 'MediaObject', contentUrl: img.src,
        name: img.alt || d.articleTitle});
    });
    schema.textContent = JSON.stringify({
      '@context': 'https://schema.org', '@graph': graph
    });
    observer.observe(c, {subtree: true, childList: true,
      characterData: true, attributes: true});
  }
  scan();
});
</script>
</body>
</html>
```

