# ArticleCalendarSection

## Purpose
Article archive with month navigation, date filtering and pagination. Use on archive pages, not inside individual articles.

## Inputs
Static HTML has no props or imports. Configure these values in the page script.

| Name | Type | Description |
|---|---|---|
| `title` | string | Required section heading |
| `articles` | Article[] | Required complete collection |
| `paginatedArticles` | Article[] | Required visible subset; derived below |
| `currentPage` | number | Required active page |
| `totalPages` | number | Required page count |
| `pageSize` | number | Required articles per page |
| `paginationBasePath` | string | Required pagination URL base |
| `id` | string | Optional section ID; default `calendar` |
| `paginationHash` | string | Optional URL fragment |
| `selectedDate` | Date | Optional initial date filter |
| `onDateSelect` | function(Date) | Optional selection callback |

`Article`: `slug`, `title`, `date` (ISO string); optional `description`, `image` strings.

## Semantic hints
`calendar`, `schedule`, `dates`, `events-calendar`, `date-picker`, `archive`, `timeline`

## Working example — archive.html
Serve at the configured base path. JavaScript updates the calendar and list; pagination links retain navigable URLs.

```html
<!doctype html>
<html lang="en">
<meta charset="utf-8">
<meta name="viewport" content="width=device-width">
<title>Article Archive</title>
<style>
[role=row]{display:grid;grid-template-columns:repeat(7,1fr)}
[aria-selected=true]{background:#cdf}
[aria-current=date]{outline:2px solid}
</style>
<section id="calendar" aria-labelledby="heading">
<h2 id="heading"></h2>
<button id="prev" aria-label="Previous month">←</button>
<span id="month" aria-live="polite"></span>
<button id="next" aria-label="Next month">→</button>
<div id="grid" role="grid" aria-label="Article dates"></div>
<button id="clear">Show all dates</button>
<div id="list"></div>
<nav id="pages" aria-label="Article pagination"></nav>
</section>
<script>
const title="Article Archive",pageSize=9,
paginationBasePath="/archive.html",paginationHash="#calendar";
const articles=[
{slug:"/welcome.html",title:"Welcome",date:"2024-01-15"}
];
let currentPage=+(new URLSearchParams(location.search).get("page"))||1,
selectedDate,view=new Date(),onDateSelect;
const $=id=>document.getElementById(id);
$("heading").textContent=title;
function render(){
const y=view.getFullYear(),m=view.getMonth();
$("month").textContent=view.toLocaleDateString(undefined,{month:"long",year:"numeric"});
$("grid").replaceChildren();
let row=document.createElement("div");row.role="row";
"Sun Mon Tue Wed Thu Fri Sat".split(" ").forEach(day=>{
const h=document.createElement("span");h.role="columnheader";h.textContent=day;row.append(h);
});
$("grid").append(row);
const offset=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate();
for(let i=0;i<Math.ceil((offset+days)/7)*7;i++){
if(i%7===0){row=document.createElement("div");row.role="row";$("grid").append(row)}
const cell=document.createElement("div");cell.role="gridcell";row.append(cell);
const n=i-offset+1;if(n<1||n>days)continue;
const d=new Date(y,m,n),key=d.toLocaleDateString("en-CA"),
b=document.createElement("button");
b.textContent=n+(articles.some(a=>a.date.slice(0,10)===key)?" •":"");
b.setAttribute("aria-label",d.toDateString());
cell.setAttribute("aria-selected",String(selectedDate?.toDateString()===d.toDateString()));
if(d.toDateString()===new Date().toDateString())b.setAttribute("aria-current","date");
b.onclick=()=>{selectedDate=d;currentPage=1;onDateSelect?.(d);render()};
cell.append(b);
}
const filtered=articles.filter(a=>!selectedDate||new Date(a.date.slice(0,10)+"T12:00").toDateString()===selectedDate.toDateString());
const totalPages=Math.max(1,Math.ceil(filtered.length/pageSize));
currentPage=Math.min(Math.max(1,currentPage),totalPages);
const paginatedArticles=filtered.slice((currentPage-1)*pageSize,currentPage*pageSize);
$("list").replaceChildren();
paginatedArticles.forEach(a=>{
const card=document.createElement("article"),link=document.createElement("a");
link.href=a.slug;link.textContent=a.title;card.append(link);$("list").append(card);
});
$("pages").replaceChildren();
for(let p=1;p<=totalPages;p++){
const a=document.createElement("a");
a.href=paginationBasePath+"?page="+p+paginationHash;a.textContent=p+" ";
if(p===currentPage)a.setAttribute("aria-current","page");
a.onclick=e=>{e.preventDefault();currentPage=p;history.pushState(null,"",a.href);render()};
$("pages").append(a);
}
}
$("prev").onclick=()=>{view=new Date(view.getFullYear(),view.getMonth()-1,1);render()};
$("next").onclick=()=>{view=new Date(view.getFullYear(),view.getMonth()+1,1);render()};
$("clear").onclick=()=>{selectedDate=undefined;currentPage=1;render()};
render();
</script>
</html>
```

